def test_workflowForAFamilyOfRawResults_responds_to_non_default_p_u_opt(initial_manual_inspection_carried_out=True):

    dict_for_all_test_sets_of_raw_subset_results,metric_we_are_interested_in,metric_to_expected_sub_1_minus_sub_2_sign = inputs_for_test_workflowForAFamilyOfRawResults()

    out_dir = os.getcwd()

    for p_u_opt in [False,True]:
        p_vals_table = f'one_tail_test_workflowForAFamilyOfRawResults_responds_to_non_default_p_u_opt_with_p_u={p_u_opt}.csv'

        p_vals_file = os.path.sep.join([out_dir,p_vals_table])

        workflowForAFamilyOfRawResults(out_dir,dict_for_all_test_sets_of_raw_subset_results,subset_1_name='Inside',subset_2_name='Outside',
                                    type_of_modelling='binary_class',no_rand_splits=100,strat_rand_split_y_name='strat_y',rand_seed=42,
                                    metrics_of_interest=[metric_we_are_interested_in],x_lab='Groups',y_lab='Shift-Metric',legend_lab='Split Basis',sig_level_perc=None,
                                    one_sided_sig_test=True,metric_to_expected_sub_1_minus_sub_2_sign=metric_to_expected_sub_1_minus_sub_2_sign,p_vals_table=p_vals_table,
                                    adjusted_p_vals_table_name=None,results_are_obtained_over_multiple_folds_and_or_seeds=True,create_plots=False,
                                    debug=True, scenarios_with_errors=[],adjust_p_vals=False,set_p_to_nan_if_metric_cannot_be_computed_for_orig_split=True,conformal_sig_level=0.32,delta_calib_prob=0.05,p_val_aggregation_option="conservative_twice_average",p_u=p_u_opt)
        
        df = pd.read_csv(p_vals_file)
        assert 1 == df.shape[0],df.shape[0]
        precursor_p_vals_str = df['all_p_vals_str'].tolist()[0]

        if p_u_opt:
            assert  approx([float(v) for v in '0.009900990099009901;0.15841584158415842;0.009900990099009901;0.009900990099009901;0.061224489795918366'.split(';')]) == [float(v) for v in precursor_p_vals_str.split(';')]
                                                                                                                                                                    
        else:
            assert  approx([float(v) for v in '0.0;0.15;0.0;0.0;0.05'.split(';')]) == [float(v) for v in precursor_p_vals_str.split(';')]


        if initial_manual_inspection_carried_out:
            os.remove(p_vals_file)

def test_workflowForAFamilyOfRawResults_responds_to_non_default_p_val_agg_opt(initial_manual_inspection_carried_out=True):

    dict_for_all_test_sets_of_raw_subset_results,metric_we_are_interested_in,metric_to_expected_sub_1_minus_sub_2_sign = inputs_for_test_workflowForAFamilyOfRawResults()

    out_dir = os.getcwd()

    for p_val_agg_opt in ["conservative_twice_average","cct"]:
        p_vals_table = f'one_tail_test_workflowForAFamilyOfRawResults_responds_to_non_default_p_val_agg_opt_with_p_val_agg_opt={p_val_agg_opt}.csv'

        p_vals_file = os.path.sep.join([out_dir,p_vals_table])

        workflowForAFamilyOfRawResults(out_dir,dict_for_all_test_sets_of_raw_subset_results,subset_1_name='Inside',subset_2_name='Outside',
                                    type_of_modelling='binary_class',no_rand_splits=100,strat_rand_split_y_name='strat_y',rand_seed=42,
                                    metrics_of_interest=[metric_we_are_interested_in],x_lab='Groups',y_lab='Shift-Metric',legend_lab='Split Basis',sig_level_perc=None,
                                    one_sided_sig_test=True,metric_to_expected_sub_1_minus_sub_2_sign=metric_to_expected_sub_1_minus_sub_2_sign,p_vals_table=p_vals_table,
                                    adjusted_p_vals_table_name=None,results_are_obtained_over_multiple_folds_and_or_seeds=True,create_plots=False,
                                    debug=True, scenarios_with_errors=[],adjust_p_vals=False,set_p_to_nan_if_metric_cannot_be_computed_for_orig_split=True,conformal_sig_level=0.32,delta_calib_prob=0.05,p_val_aggregation_option=p_val_agg_opt,p_u=True)
        
        df = pd.read_csv(p_vals_file)
        assert 1 == df.shape[0],df.shape[0]
        combined_p_val = df['Shift-Metric P-value'].tolist()[0]

        if "conservative_twice_average" == p_val_agg_opt:
            #Manually computed based on precursor_p_vals_str observed for previous test:
            assert approx(combined_p_val) == 0.0997373206708426
            assert not approx(0.099001) == 0.0997373206708426
            #assert 0.09900990099009901 == combined_p_val
        elif "cct" == p_val_agg_opt:
            if initial_manual_inspection_carried_out:
                assert approx(combined_p_val) == 0.015381337485294022
        else:
            raise Exception(f'Unexpected option={p_val_agg_opt}')


        if initial_manual_inspection_carried_out:
            os.remove(p_vals_file)

def test_aggregate_p_vals_cct_works_with_nan_values(initial_manual_inspection_carried_out=True):
    
    p_vals = [0.05,0.55,0.04,0.2,np.nan]

    combined_p = aggregate_p_vals(list_of_p_vals=p_vals,p_val_aggregation_option="cct")

    assert isinstance(combined_p,float)
    assert not pd.isna(combined_p)

    #################################################
    #https://doi.org/10.1080/01621459.2018.1554485
    #Cauchy Combination test is dominated by the few smallest p-values
    assert combined_p < (aggregate_p_vals(list_of_p_vals=p_vals,p_val_aggregation_option="conservative_twice_average",clip_conservative_twice_average=False)/2)
    ##################################################

    if initial_manual_inspection_carried_out:
        observed_val = 0.0806518921347118
        assert combined_p == observed_val
    else:
        print(f'{report_name_of_function_where_this_is_called()}:combined_p={combined_p}')

def test_aggregate_p_vals_cct_works_with_all_nan_values():
    
    p_vals = [np.nan,np.nan]

    combined_p = aggregate_p_vals(list_of_p_vals=p_vals,p_val_aggregation_option="cct")

    assert pd.isna(combined_p)

def test_consistentlyDiscretizeEndpointValues_for_fix_reg_y_dicretization_eq_True():

    y_set_one_discretized,y_set_two_discretized,discretizer = consistentlyDiscretizeEndpointValues(y_set_one_list=list([float(v+1) for v in range(10)]),y_set_two_list=list([float(v+11) for v in range(10)]),n_bins=5,rand_seed=42,fix_reg_y_dicretization=True)

    assert [0]*4 + [1]*4 + [2]*2 == y_set_one_discretized,f'y_set_one_discretized={y_set_one_discretized}'
    assert [2]*2 + [3]*4 + [4]*4 == y_set_two_discretized,f'y_set_two_discretized={y_set_two_discretized}'


